import sys
import csv


def main():
    if len(sys.argv) != 4:
        print(f"Usage: python {sys.argv[0]} <csv_file> <group_column> <sum_column>")
        sys.exit(1)

    csv_file = sys.argv[1]
    group_column = sys.argv[2]
    sum_column = sys.argv[3]

    groups = {}

    try:
        with open(csv_file, newline='') as f:
            reader = csv.DictReader(f)
            for row in reader:
                group = row.get(group_column)
                if group is None:
                    print(f"Error: Group column '{group_column}' not found in CSV header.")
                    sys.exit(1)
                sum_value_str = row.get(sum_column)
                if sum_value_str is None:
                    print(f"Error: Sum column '{sum_column}' not found in CSV header.")
                    sys.exit(1)
                try:
                    sum_value = int(sum_value_str)
                except ValueError:
                    print(f"Warning: Non-integer value '{sum_value_str}' in sum column '{sum_column}' ignored.")
                    continue

                groups[group] = groups.get(group, 0) + sum_value

    except FileNotFoundError:
        print(f"Error: File '{csv_file}' not found.")
        sys.exit(1)

    for group in sorted(groups):
        print(f"{group},{groups[group]}")


if __name__ == '__main__':
    main()

