import sys
import csv


def main():
    if len(sys.argv) != 4:
        print(f"Usage: python {sys.argv[0]} <csv_file> <group_column> <sum_column>")
        sys.exit(1)

    csv_file = sys.argv[1]
    group_column = sys.argv[2]
    sum_column = sys.argv[3]

    groups = {}

    with open(csv_file, newline='') as f:
        reader = csv.DictReader(f)
        for row in reader:
            group_key = row[group_column]
            try:
                value = int(row[sum_column])
            except ValueError:
                value = 0
            groups[group_key] = groups.get(group_key, 0) + value

    for group in sorted(groups):
        print(f"{group},{groups[group]}")


if __name__ == '__main__':
    main()

